    } catch (error) {
      await restoreOnSideEffectFailure(deps.repo, existing, target);
      throw error;
    }
  }

  return { activation };
}

export interface GetActivationRequired {
  deps: { repo: PluginActivationRepoPort };
  input: { workspaceId: UUID; pluginId: string };
