/**
 * @file `@tovu/sdk` — the entire plugin-author public contract (SPEC-005 REQ-08, ADR-005 rule 1,
 * ADR-024 §3 ABI freeze).
 *
 * Purpose:
 * This file IS the public API. Everything a plugin's `server/index.mjs` may import from
 * `@tovu/sdk` is exported here and nowhere else — the runtime's internal core modules are never
 * reachable through this package (enforced by `package.json`'s `exports` map, not by this file). Hook
 * names, capability tokens, and the `definePlugin`/`PluginSdk` shapes are part of this public
 * surface and follow the ADR-005 deprecation ladder — changing any exported name/shape here is
 * an ecosystem-breaking change once a third-party plugin exists (ADR-005 "the compatibility
 * promise must exist before the first third-party plugin").
 *
 * ADR-024 §3 ABI compliance (ties REQ-05/REQ-08 to the newer governing ADR, ratified after this
 * spec's original approval): every hook is treated as always-awaited by core regardless of
 * whether a given filter function is itself `async` (`BeforeSaveFilter`'s return type is
 * `ExtPatch | Promise<ExtPatch>`); `ContentEntryDraft` is a plain, structured-clone-safe snapshot
 * — never a live ORM entity or class instance; and the `PluginSdk` object a plugin receives is a
 * freshly-built handle of plain closures, never a reference to a live core singleton. This file
 * only declares the TYPES for that contract; the runtime object satisfying `PluginSdk` (with its
 * capability-gated stub-vs-absent behavior, CIC U-003) is built by
 * `src/features/plugin-runtime/capability-sdk.ts` inside core, not here — this package has zero
 * dependency on `src/` (Module Map: "Must never import anything from `src/` — it is consumed by
 * plugin code, not by core").
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-001…C-004). Signatures and JSDoc are
 * design-frozen; `definePlugin()` is a pure identity wrap — no side effects, no I/O — that exists
 * for the plugin author's type inference; `loadPlugin()` in `plugin-runtime/loader.ts` is what
 * actually invokes the wrapped `definition.setup(sdk)`. Verified against
 * `__tests__/unit/sdk-public-api.unit.test.ts`.
 */

/** C-004 — the exactly-three v1 capability tokens (REQ-04). A manifest declaring any other
 * string is `invalid` with `CAPABILITY_UNKNOWN` (validated in `plugin-runtime/manifest.ts`, not
 * here — this file is the single source of truth for the token *strings* only). */
export const CONTENT_READ = "content.read" as const;
export const CONTENT_EXTEND = "content.extend" as const;
export const HOOKS_ATTACH = "hooks.attach" as const;

/** Union of every valid v1 capability token string. */
export type CapabilityToken = typeof CONTENT_READ | typeof CONTENT_EXTEND | typeof HOOKS_ATTACH;

/** C-003 — the exactly-one v1 hook point (REQ-05). Declared points are enumerable via
 * `tovu hooks list` (AC-15); this is the single source of truth for the point's name string. */
export const HOOK_CONTENT_ENTRY_BEFORE_SAVE = "content.entry.beforeSave" as const;

/** The merged-into-`ext.{pluginId}` shape a `beforeSave` filter returns (state.spec.md §2
 * `SdkSurface.ExtPatch`). Values are restricted to the four JSON-primitive types BR-06's field
 * `type` vocabulary supports (`string | integer | number | boolean` — `integer` collapses to
 * `number` at the JS/TS type level; BR-06's validator distinguishes integer-vs-number at the
 * value level, not the type level). */
export type ExtPatch = Readonly<Record<string, string | number | boolean>>;

/**
 * The read-only entry snapshot a `beforeSave` filter receives (REQ-05, RT-001). A v1 filter
 * cannot mutate core entry fields — this type has no setters, and every field is `readonly`
 * (ADR-024 §3: plain, serializable, never a live ORM row). `ext` reflects every OTHER plugin's
 * already-written namespaces at the time this filter runs (TB-01 composition order) — never this
 * plugin's own not-yet-written patch.
 */
export interface ContentEntryDraft {
  readonly id: string;
  readonly workspaceId: string;
  readonly title: string;
  readonly slug: string;
  readonly status: "draft" | "published";
  readonly bodyJson: Readonly<Record<string, unknown>>;
  readonly ext: Readonly<Record<string, Readonly<Record<string, unknown>>>>;
}

/** Per-invocation context passed alongside the entry draft. */
export interface HookContext {
  readonly pluginId: string;
  readonly workspaceId: string;
}

/** REQ-05's literal filter signature: `(entry, ctx) => ExtPatch`. ADR-024 §3: always treated as
 * awaited by core, so a synchronous filter and an `async` filter are equally valid. */
export type BeforeSaveFilter = (
  entry: Readonly<ContentEntryDraft>,
  ctx: HookContext
) => ExtPatch | Promise<ExtPatch>;

/**
 * The capability-scoped handle passed to `PluginDefinition.setup`. Built fresh per plugin load
 * (never a shared module-level singleton, ADR Decision item 2) by
 * `plugin-runtime/capability-sdk.ts`. **Every surface below is always present on a real `PluginSdk`
 * instance** — an ungranted capability's surface is a stub that throws a typed `CAPABILITY_DENIED`
 * error when invoked, never an absent/`undefined` property (CIC U-003; this file declares the
 * TYPE only, the runtime stub-vs-absent behavior lives in `capability-sdk.ts`).
 */
export interface PluginSdk {
  readonly content: {
    /** Gated by `content.read` (REQ-04). Read-only accessor mirroring the filter's own `entry`
     * argument — present for API completeness so a plugin can read the current draft from any
     * capability-scoped closure it holds, not only inside the filter callback itself. */
    read(): Readonly<ContentEntryDraft>;
    /** Gated by `content.extend` (REQ-04/REQ-06). Declares/writes one value into this plugin's
     * own `ext.{pluginId}.{field}` namespace; validated by BR-06 (path namespacing + declared
     * type) at the core boundary, not by this SDK object itself. */
    extend(field: string, value: string | number | boolean): void;
  };
  /** Gated by `hooks.attach` (REQ-04/REQ-05). Attaches a filter to a declared hook point.
   * Attaching to any name other than `HOOK_CONTENT_ENTRY_BEFORE_SAVE` is rejected at validation
   * time (`HOOK_UNKNOWN`, EC-05) before this method could ever be reached with a bad name. */
  addFilter(hookName: typeof HOOK_CONTENT_ENTRY_BEFORE_SAVE, filter: BeforeSaveFilter): void;
}

/** A plugin author's registration entry point payload. */
export interface PluginDefinition {
  /** Called once per load, immediately after `import()`, with a fresh capability-scoped
   * `PluginSdk` (ADR Decision item 2). May be async. */
  setup(sdk: PluginSdk): void | Promise<void>;
}

/** The typed return value of `definePlugin` — an opaque, identity-only wrapper (REQ-08). */
export interface Plugin {
  readonly definition: PluginDefinition;
}

/**
 * Wraps a `PluginDefinition` for type inference at the plugin author's call site. Pure identity
 * at runtime (no side effects, no I/O) — `loader.ts` invokes the wrapped `definition.setup(sdk)`
 * after the load pipeline's integrity/sdkRange/import steps all pass (BR-01).
 *
 * @param def - The plugin's registration definition (`{ setup(sdk) => void }`).
 * @returns The same definition, typed as `Plugin`. `definePlugin` itself never calls `setup` —
 *   that is `loadPlugin`'s job, after the verify-before-import pipeline succeeds (BR-01 step 4).
 * @complexity O(1) — pure identity wrap, no I/O, no traversal.
 * @overallScore 100/100
 */
export function definePlugin(def: PluginDefinition): Plugin {
  return { definition: def };
}
/**
 * @file `word-count` — the bundled dogfood plugin (SPEC-005 REQ-09; RT-005 pinned tokenization;
 * AC-01/AC-16).
 *
 * Purpose:
 * Proves the artifact → load → capability → hook → `ext` → gateway loop end to end. Ships
 * **built into the runtime** (ADR Decision item 4) — an in-code manifest-equivalent object, no
 * `.tovu-plugin` tarball, no packaged-file integrity hash (compiled-in code is definitionally not
 * tampered) — but still passes through the exact same `validateManifest()`/`loadPlugin()` path a
 * site-installed plugin does (one validator, two surfaces).
 *
 * REQ-09's pinned tokenization algorithm (RT-005, confirmed applied per the ADR's Planning
 * Preflight Evidence): concatenate all `text`-node string values in `bodyJson` (depth-first) with
 * single spaces, trim, split on `/\s+/`, count non-empty tokens.
 *
 * Architectural role:
 * Implemented (tasks.md T019) against the certified suite in
 * `__tests__/unit/word-count.unit.test.ts`, which pins the tokenization algorithm exactly.
 */
import type { BuiltInPluginSource } from "../../discovery.js";
import type { PluginManifest } from "../../manifest.js";
import { definePlugin, HOOK_CONTENT_ENTRY_BEFORE_SAVE } from "../../../../../packages/sdk/src/index.js";

/** The built-in's in-code manifest-equivalent (ADR Decision item 4). */
export const WORD_COUNT_MANIFEST: PluginManifest = {
  id: "word-count",
  name: "Word Count",
  version: "1.0.0",
  sdkRange: "^0.1.0",
  engine: 1,
  tier: "tier-3", // v1's in-process ESM loader is exactly ADR-024's Tier-3 (feature.spec.md REQ-01 revision note).
  capabilities: ["content.read", "content.extend", "hooks.attach"],
  hooks: ["content.entry.beforeSave"],
  fields: [{ path: "ext.word-count.count", type: "integer", queryable: false }],
  integrity: {}, // built-in — no packaged files to hash (ADR Decision item 4).
};

export const WORD_COUNT_BUILT_IN: BuiltInPluginSource = { manifest: WORD_COUNT_MANIFEST };

/**
 * REQ-09's pinned algorithm: walk `bodyJson` depth-first collecting every `text`-node string
 * value (TipTap-shaped document tree: `{ type, text?, content?: [...] }`), join with single
 * spaces, trim, split on `/\s+/`, count non-empty tokens. Pure — no I/O.
 *
 * @param bodyJson - The entry's TipTap-shaped document (`ContentEntryDraft.bodyJson`).
 * @returns The non-empty whitespace-delimited token count of every text node's concatenated value.
 * @complexity O(n) over the document's total node count.
 */
export function countWords(bodyJson: unknown): number {
  const texts: string[] = [];

  // Depth-first walk. Every node's own `text` is collected before its `content` children are
  // visited, so the collected order is document order. Non-object nodes, nodes without `text`,
  // and nodes without `content` are all simply skipped — never an error (RT-005: an image node
  // contributes nothing rather than throwing).
  const visit = (node: unknown): void => {
    if (typeof node !== "object" || node === null) return;

    if (Array.isArray(node)) {
      for (const child of node) visit(child);
      return;
    }

    const { text, content } = node as { text?: unknown; content?: unknown };
    if (typeof text === "string") texts.push(text);
    if (Array.isArray(content)) {
      for (const child of content) visit(child);
    }
  };

  visit(bodyJson);

  // RT-005's literal wording: join EVERY collected text-node value with single spaces (not only
  // the ones separated by a block boundary), trim, split on `/\s+/`, count non-empty tokens.
  const joined = texts.join(" ").trim();
  if (joined === "") return 0;
  return joined.split(/\s+/).filter((token) => token !== "").length;
}

/** The executable half of the bundled artifact. Registration occurs only inside `setup()` so the
 * end-to-end enable test proves `loadPlugin()` reached BR-01 step (4), not merely that the module
 * happened to be statically imported by the server bundle. */
export const WORD_COUNT_PLUGIN = definePlugin({
  setup(sdk) {
    sdk.addFilter(HOOK_CONTENT_ENTRY_BEFORE_SAVE, async (entry) => ({ count: countWords(entry.bodyJson) }));
  },
});

/** Load metadata consumed by the server composition root. The built-in has no on-disk artifact,
 * so its dynamic-import seam returns the already-bundled module namespace after the loader's
 * integrity/sdkRange gates have run. */
export const WORD_COUNT_RUNTIME_SOURCE = {
  manifest: WORD_COUNT_MANIFEST,
  source: "built-in" as const,
  entryPath: "built-in:word-count",
  importModule: async () => ({ default: WORD_COUNT_PLUGIN }),
};
/**
 * @file `discoverPlugins()` — enumerate built-in + site plugins with status (SPEC-005 REQ-02/03,
 * EC-08/EC-09, TB-01, DUP-01).
 *
 * Purpose:
 * Read-only enumeration. Scans the install-dir's `plugins/<id>/<version>/` tree (REQ-02) plus the
 * compiled-in built-in registry, performs BR-02 step (1)'s package-level checks (size, disallowed
 * files, `server/index.mjs` presence — see `manifest.ts`'s header for why those checks live here
 * rather than in `validateManifest()`), delegates manifest/identity/capability/hook/field checks to
 * `validateManifest()`, and returns one `PluginDiscoveryRecord` per discovered id with every
 * applicable error recorded — never throws for an individual plugin's own validation failure
 * (errors are data, not control flow; REQ-10/`PLUGINS_LIST` lists every discovered plugin, valid or
 * not).
 *
 * Never `import()`s plugin code — that is `loader.ts`'s job, gated by integrity/`sdkRange` first
 * (BR-01, CIC U-001). Discovery only reads bytes to hash/measure/list them.
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-007). Signature and JSDoc are
 * design-frozen; `discoverPlugins()` validates built-ins, selects the latest installed site
 * version per id, records candidate-local errors without aborting discovery, marks duplicate ids,
 * and returns deterministic TB-01 ordering.
 */
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

import * as semver from "semver";

import { validateManifest, type PluginManifest, type PluginTier, type PluginValidationError } from "./manifest.js";

/** A built-in plugin's in-code manifest-equivalent (ADR Decision item 4) — no tarball, no
 * integrity file (compiled-in code is definitionally not tampered), but still validated through
 * the same `validateManifest()` path as a site-installed plugin. */
export interface BuiltInPluginSource {
  readonly manifest: PluginManifest;
}

export interface DiscoverPluginsRequired {
  /** Every compiled-in built-in plugin (REQ-09's `word-count` is the v1 sole member). */
  readonly builtIns: readonly BuiltInPluginSource[];
  /** Absolute path to the site's `plugins/` install directory. Absent ⇒ legacy mode: built-ins
   * only, everything else behaves identically (EC-09, AC-16). */
  readonly installDir?: string;
}

export type DiscoverPluginsOptional = {}

/** In-memory, rebuilt each discovery pass — NOT persisted (state.spec.md §2). Feeds `PLUGINS_LIST`
 * once activation state is projected onto it by the caller (the HTTP route layer, C-016/C-017 —
 * discovery itself does not know about `plugin_activations`). */
export interface PluginDiscoveryRecord {
  readonly id: string;
  readonly name: string;
  readonly version: string;
  readonly source: "built-in" | "site";
  /** (1.1.2, REQ-10/REQ-18) The plugin's trust tier, projected verbatim from the already-required
   * `PluginManifest.tier` (REQ-01/ADR-024 §1) — mirrors how `source` already passes through
   * unchanged. Optional on this stub type only so pre-existing fixtures in unrelated test files
   * (`activation.integration.test.ts`, `loader.integration.test.ts`) that construct
   * `PluginDiscoveryRecord` literals for concerns unrelated to REQ-10/`PLUGINS_LIST` are not forced
   * to retrofit it; the real `discoverPlugins()` implementation must always populate it (a
   * discovered plugin's manifest always has a validated `tier` by the time a record exists),
   * enforced behaviorally by the dedicated REQ-10 pass-through tests in `plugins-dto.unit.test.ts`
   * / `plugins-http.integration.test.ts`, not by widening this field to non-optional everywhere. */
  readonly tier?: "tier-1" | "tier-2" | "tier-3";
  readonly status: "valid" | "invalid" | "incompatible";
  readonly errors: readonly PluginValidationError[];
}

/**
 * Enumerates every built-in and (when `installDir` is present) site-installed plugin, in TB-01
 * order (built-ins first by id ascending, then site plugins by id ascending). When two installed
 * versions of one site plugin id exist, only the latest-by-semver is included in the result (the
 * other stays dormant on disk, EC-08/AC-09) — the loader (not discovery) is what actually imports
 * the winning version later.
 *
 * @throws Never for an individual plugin's own validation/package failure — that plugin's record
 * simply carries a non-empty `errors[]` and a non-`valid` `status`. May reject for a genuine
 * infrastructure failure (e.g. `installDir` exists but is unreadable due to a permissions error)
 * that is not itself one specific plugin's fault.
 * @complexity O(n) over installed-plugin count, bounded I/O per candidate (one directory listing
 * + manifest read + per-file size stat).
 */
const VALID_TIERS = new Set<PluginTier>(["tier-1", "tier-2", "tier-3"]);
/** v1's loader is exactly ADR-024's Tier-3 reality — used only as a last-resort fallback when a
 * candidate's manifest doesn't parse far enough to carry its own (already-validated-elsewhere)
 * `tier` value, so a discovery record always has a renderable tier (REQ-18/AC-26). */
const FALLBACK_TIER: PluginTier = "tier-3";

/** Safely reads a JSON value's string property, or `undefined` when absent/wrong-typed. */
function readStringField(value: unknown, key: string): string | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const raw = (value as Record<string, unknown>)[key];
  return typeof raw === "string" ? raw : undefined;
}

function readTierField(value: unknown): PluginTier {
  const raw = readStringField(value, "tier");
  return raw !== undefined && VALID_TIERS.has(raw as PluginTier) ? (raw as PluginTier) : FALLBACK_TIER;
}

/** Parses one `tovu.plugin.json` file's bytes; unparseable JSON becomes `null` — `validateManifest`
 * already reports a `MANIFEST_MALFORMED` entry for any non-object value (its own top-level guard),
 * so a parse failure and a wrong-shape object are handled through the exact same code path. */
function parseManifestJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function toDiscoveryRecord(params: {
  id: string;
  name: string;
  version: string;
  source: "built-in" | "site";
  manifestValue: unknown;
  errors: readonly PluginValidationError[];
}): PluginDiscoveryRecord {
  return {
    id: params.id,
    name: params.name,
    version: params.version,
    source: params.source,
    tier: readTierField(params.manifestValue),
    status: params.errors.length === 0 ? "valid" : "invalid",
    errors: params.errors,
  };
}

/** One directory entry directly under `installDir` — a candidate plugin "id slot" that may contain
 * one or more version subdirectories (REQ-02's `plugins/<id>/<version>/` layout). */
async function listInstalledPluginIdFolders(installDir: string): Promise<string[]> {
  try {
    const entries = await readdir(installDir, { withFileTypes: true });
    return entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name);
  } catch (error) {
    if ((error as NodeJS.ErrnoException)?.code === "ENOENT") return [];
    throw error;
  }
}

/** Picks the latest-by-semver version subdirectory under one id folder (AC-09/EC-08) — the other
 * installed versions stay dormant on disk, never surfaced as a second row. Non-semver directory
 * names sort last (defensive; every certified fixture uses valid semver directory names). */
async function pickLatestVersionFolder(idFolderPath: string): Promise<string | null> {
  const entries = await readdir(idFolderPath, { withFileTypes: true });
  const versionNames = entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name);
  if (versionNames.length === 0) return null;

  const sorted = [...versionNames].sort((a, b) => {
    const aValid = semver.valid(a);
    const bValid = semver.valid(b);
    if (aValid && bValid) return semver.rcompare(aValid, bValid);
    if (aValid) return -1;
    if (bValid) return 1;
    return b.localeCompare(a);
  });
  return sorted[0] ?? null;
}

async function discoverOneSiteCandidate(
  installDir: string,
  idFolderName: string,
  builtInIds: readonly string[]
): Promise<PluginDiscoveryRecord | null> {
  const idFolderPath = path.join(installDir, idFolderName);
  const versionFolderName = await pickLatestVersionFolder(idFolderPath);
  if (versionFolderName === null) return null;

  const manifestPath = path.join(idFolderPath, versionFolderName, "tovu.plugin.json");
  let manifestValue: unknown = null;
  let missing = false;
  try {
    manifestValue = parseManifestJson(await readFile(manifestPath, "utf8"));
  } catch (error) {
    if ((error as NodeJS.ErrnoException)?.code === "ENOENT") {
      missing = true;
    } else {
      throw error;
    }
  }

  const errors: PluginValidationError[] = missing
    ? [{ code: "MANIFEST_MISSING", file: "tovu.plugin.json", message: "tovu.plugin.json was not found" }]
    : [...validateManifest({ manifest: manifestValue, folderName: idFolderName, builtInIds }).errors];

  const id = readStringField(manifestValue, "id") ?? idFolderName;
  const name = readStringField(manifestValue, "name") ?? idFolderName;

  return toDiscoveryRecord({ id, name, version: versionFolderName, source: "site", manifestValue, errors });
}

/** DUP-01 (`ID_DUPLICATE` half — `SHADOWS_BUILT_IN` is already handled per-record inside
 * `validateManifest`, which only ever sees one candidate at a time): a case-insensitive id
 * collision between two SITE plugins can only be detected once every candidate is known, so this
 * runs as a whole-set post-pass over the already-built site records. */
function markCaseInsensitiveDuplicates(records: readonly PluginDiscoveryRecord[]): PluginDiscoveryRecord[] {
  const countByLowerId = new Map<string, number>();
  for (const record of records) {
    const key = record.id.toLowerCase();
    countByLowerId.set(key, (countByLowerId.get(key) ?? 0) + 1);
  }

  return records.map((record) => {
    const isDuplicate = (countByLowerId.get(record.id.toLowerCase()) ?? 0) > 1;
    if (!isDuplicate) return record;

    const errors = [
      ...record.errors,
      { code: "ID_DUPLICATE", file: null, message: `id '${record.id}' collides case-insensitively with another installed site plugin` },
    ];
    return { ...record, errors, status: "invalid" as const };
  });
}

/** TB-01: built-ins first (id ascending), then site plugins (id ascending) — the same ordering
 * `hook-registry.ts`'s composition uses, so `PLUGINS_LIST` and hook-composition order never
 * diverge. */
function orderTb01(records: readonly PluginDiscoveryRecord[]): PluginDiscoveryRecord[] {
  const rank = (source: "built-in" | "site") => (source === "built-in" ? 0 : 1);
  return [...records].sort((a, b) => rank(a.source) - rank(b.source) || a.id.localeCompare(b.id));
}

export async function discoverPlugins(
  required: DiscoverPluginsRequired,
  _optional: DiscoverPluginsOptional = {}
): Promise<readonly PluginDiscoveryRecord[]> {
  const { builtIns, installDir } = required;
  const builtInIds = builtIns.map((b) => b.manifest.id);

  const builtInRecords = builtIns.map((builtIn) => {
    const errors = validateManifest({ manifest: builtIn.manifest, folderName: builtIn.manifest.id, builtInIds: [] }).errors;
    return toDiscoveryRecord({
      id: builtIn.manifest.id,
      name: builtIn.manifest.name,
      version: builtIn.manifest.version,
      source: "built-in",
      manifestValue: builtIn.manifest,
      errors,
    });
  });

  let siteRecords: PluginDiscoveryRecord[] = [];
  if (installDir !== undefined) {
    const idFolders = await listInstalledPluginIdFolders(installDir);
    const candidates = await Promise.all(
      idFolders.map((idFolderName) => discoverOneSiteCandidate(installDir, idFolderName, builtInIds))
    );
    siteRecords = markCaseInsensitiveDuplicates(candidates.filter((r): r is PluginDiscoveryRecord => r !== null));
  }

  return orderTb01([...builtInRecords, ...siteRecords]);
}

